import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { network } from "hardhat";
import { encodePacked, keccak256, toHex, type Hex } from "viem";
import { revertName, vectors } from "./naming-helpers";

// The naming rule: a Rome token's name and symbol are exactly the origin's, unchanged, after the checks on the
// WHOLE text. Every entry of the shared vector file (tests/fixtures/asset-naming/vectors.json, generated by an
// independent reference from Unicode 16.0.0's data) must give the same two strings, or the same refusal, from
// the library. The one cut is the Solana Metaplex metadata (32 and 10 bytes): each passing vector carries it.
describe("the naming rule", async () => {
    const { viem } = await network.connect();
    const h = await viem.deployContract("RomeNamingHarness");

    it("the vector file is from Unicode 16.0.0 with the 23-range, 235-code-point table", () => {
        assert.equal(vectors.unicodeVersion, "16.0.0");
        assert.equal(vectors.table.length, 23);
        const n = vectors.table.reduce((a, [lo, hi]) => a + (hi - lo + 1), 0);
        assert.equal(n, 235);
        assert.ok(vectors.text.length > 500, "a large vector set");
    });

    it("every name and symbol vector gives the origin's own string, unchanged, or the reference's refusal", async () => {
        const bad: string[] = [];
        for (const v of vectors.text) {
            const call = v.kind === "name" ? h.read.romeName([v.input]) : h.read.romeSymbol([v.input]);
            if (v.expect.ok) {
                const got = await call;
                if ((got as string).toLowerCase() !== v.expect.output.toLowerCase()) bad.push(`${v.id}: got ${got}, want ${v.expect.output}`);
                // nothing is added and nothing is cut: the output is the input
                if (v.expect.output.toLowerCase() !== v.input.toLowerCase()) bad.push(`${v.id}: vector output differs from its input`);
            } else {
                const err = await revertName(call);
                if (err !== v.expect.error) bad.push(`${v.id}: got ${err}, want ${v.expect.error}`);
            }
        }
        assert.deepEqual(bad, []);
    });

    it("the table: every code point from 0 to U+10FFFF is classed as Unicode 16.0.0 says", async () => {
        // The contract and a reference built from the file's 23 ranges walk the same chunks and chain the
        // matching code points into one hash, so the chunk's count and digest must both agree.
        const inTable = (cp: number) => vectors.table.some(([lo, hi]) => cp >= lo && cp <= hi);
        const CHUNK = 0x2000;
        for (let from = 0; from < 0x110000; from += CHUNK) {
            const to = Math.min(from + CHUNK, 0x110000);
            let count = 0n;
            let digest: Hex = `0x${"00".repeat(32)}`;
            for (let cp = from; cp < to; cp++) {
                if (inTable(cp)) {
                    count++;
                    digest = keccak256(encodePacked(["bytes32", "uint32"], [digest, cp]));
                }
            }
            const [gotCount, gotDigest] = (await h.read.table([BigInt(from), BigInt(to)])) as [bigint, Hex];
            assert.equal(gotCount, count, `count in ${from.toString(16)}..${to.toString(16)}`);
            assert.equal(gotDigest, digest, `digest in ${from.toString(16)}..${to.toString(16)}`);
        }
    });

    it("every passing vector carries its Metaplex cut: 32 bytes of name, 10 of symbol, on a UTF-8 boundary", async () => {
        const [nameMax, symbolMax] = (await h.read.metaplexLimits()) as [bigint, bigint];
        assert.equal(nameMax, 32n);
        assert.equal(symbolMax, 10n);
        const bad: string[] = [];
        let longer = 0;
        for (const v of vectors.text) {
            if (!v.expect.ok) continue;
            const max = v.kind === "name" ? nameMax : symbolMax;
            const got = (await h.read.cut([v.input, max])) as string;
            if (got.toLowerCase() !== v.expect.metaplex.toLowerCase()) bad.push(`${v.id}: got ${got}, want ${v.expect.metaplex}`);
            if (v.input.length > v.expect.metaplex.length) longer++;
        }
        assert.deepEqual(bad, []);
        assert.ok(longer > 20, "the set holds texts longer than Metaplex keeps");
    });

    it("the names are the origin's: no ro, no (Rome), no cut", async () => {
        const text = (s: string) => toHex(s);
        assert.equal(await h.read.romeName([text("Tether USD")]), text("Tether USD"));
        assert.equal(await h.read.romeSymbol([text("USDT")]), text("USDT"));
        assert.equal(await h.read.romeSymbol([text("roETH")]), text("roETH"));
        const long = "A".repeat(60);
        assert.equal(await h.read.romeName([text(long)]), text(long));
        assert.equal(await h.read.romeSymbol([text("ABCDEFGHIJKLMNOP")]), text("ABCDEFGHIJKLMNOP"));
    });

    it("the cost is linear and recorded: ASCII is a word at a time", async () => {
        const client = await viem.getPublicClient();
        const rows: string[] = [];
        const cost: Record<string, bigint> = {};
        for (const v of vectors.text.filter((t) => t.id.startsWith("symbol/len/") || t.id.startsWith("name/len/"))) {
            const fn = v.kind === "name" ? "romeName" : "romeSymbol";
            const gas = await client.estimateContractGas({
                address: h.address,
                abi: h.abi,
                functionName: fn,
                args: [v.input],
            });
            cost[v.id] = gas;
            rows.push(`${v.id.padEnd(28)} ${String((v.input.length - 2) / 2).padStart(4)} bytes  ${gas} gas`);
        }
        console.log("naming cost (gas, harness call incl. 21000 base):\n" + rows.join("\n"));
        // Linear in the length, never quadratic: 200 ASCII bytes cost well under ten times what 10 bytes do, and
        // a 200-byte text of characters that all meet the table stays inside a call's budget.
        assert.ok(cost["symbol/len/ascii-200"] < 10n * cost["symbol/len/ascii-10"]);
        for (const [id, gas] of Object.entries(cost)) assert.ok(gas < 3_000_000n, `${id}: ${gas}`);
    });
});
